select * from(
select TPD.TRADE_ID bizCode, /*金融产品交易汇总业务流程.交易编号*/ '01' statusValid,/*“流程中” as 有效状态*/ TPDA.ENTRUST_ID,/*金融产品交易附属业务流程.委托代码*/ fp1.FINPROD_NAME chlFinprodId, PP.PORTFOLIO_ID,/*金融产品交易附属业务流程.投资组合代码*/ PP.PORTFOLIO_NAME,/*组合.组合名称*/ TPD.FINPROD_TYPE2,/*金融产品交易业务流程.金融产品类型*/ TPD.FINPROD_ID,/*金融产品交易业务流程.金融产品代码*/
