FPT.TYPE_6 projectType,/*金融产品分类.行内一级分类*/
FPT.TYPE_9 type9,/*金融产品分类.行内二级分类*/ FPT.TYPE_10 type10,/*金融产品分类.行内三级分类*/ FPT.TYPE_11 type11,/*金融产品分类.行内四级分类*/
FP.FINPROD_MARKET_ID,/*标的类金融产品.市场代码*/ nvl(FP.FINPROD_ABBR, FP.FINPROD_NAME) finprodName,/*标的类金融产品.金融产品简称*/ TPD.PS,/*金融产品交易业务流程.交易方向*/ TPD.PRIN_AMT,/*金融产品交易业务流程.交易本金*/ TPD.UNIT_CPRICE,/*金融产品交易业务流程.单位净价*/ TPD.UNIT_FPRICE,/*金融产品交易业务流程.单位全价*/ TPD.CCY,/*金融产品交易业务流程.交易币种*/ TO_CHAR(TPD.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE,/*金融产品交易业务流程.交易日*/ TPD.REMARK,/*金融产品交易业务流程.备注*/ TPD.WORKFLOW_ID,/*金融产品交易业务流程.工作流代码*/ TPD.WORKFLOW_STATUS status,/*金融产品交易业务流程.数据状态*/ TPD.TRADE_AMT TRADE_AMT /*交易金额*/ from
WFL_TRD_PRODUCT_DEAL TPD left join WFL_TRD_FIN_PRODUCT_DEAL_TOTAL deal on deal.TOTLE_TRADE_ID=TPD.TOTLE_TRADE_ID and deal.PS=TPD.PS left join WFL_TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID=TPDA.TRADE_ID left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID left join FIN_PRODUCT FP on FP.FINPROD_ID = TPD.FINPROD_ID LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = TPD.CHL_ID left join FIN_PRODUCT_TYPE FPT on FP.FINPROD_ID=FPT.FINPROD_ID where TPD.IS_CANCEL != #{YES} and TPD.TRADE_STATUS = #{TRADE_STATUS01} AND TPD.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND TPD.PS IN (#{T01}, #{T02}, #{T40}) AND (DEAL.IS_OVERDUE_DEAL IS NULL OR DEAL.IS_OVERDUE_DEAL != 'Y')
UNION ALL
select deal.TOTLE_TRADE_ID bizCode, /*金融产品交易业务流程.交易编号*/ '02' statusValid, TPDA.ENTRUST_ID,/*金融产品交易附属业务流程.委托代码*/ fp1.FINPROD_NAME chlFinprodId, PP.PORTFOLIO_ID,/*金融产品交易附属业务流程.投资组合代码*/ PP.PORTFOLIO_NAME,/*组合.组合名称*/ TPD.FINPROD_TYPE2,/*金融产品交易业务流程.金融产品类型*/ TPD.FINPROD_ID,/*金融产品交易业务流程.金融产品代码*/ TPD.CHL_ID chlId,/*金融产品交易业务流程.通道代码*/ FPT.TYPE_6 projectType,/*金融产品分类.行内一级分类*/ FPT.TYPE_9 type9,/*金融产品分类.行内二级分类*/ FPT.TYPE_10 type10,/*金融产品分类.行内三级分类*/ FPT.TYPE_11 type11,/*金融产品分类.行内四级分类*/ FP.FINPROD_MARKET_ID,/*标的类金融产品.市场代码*/ nvl(FP.FINPROD_ABBR, FP.FINPROD_NAME) finprodName,/*标的类金融产品.金融产品简称*/ TPD.PS,/*金融产品交易业务流程.交易方向*/ TPD.PRIN_AMT,/*金融产品交易业务流程.交易本金*/ TPD.UNIT_CPRICE,/*金融产品交易业务流程.单位净价*/ TPD.UNIT_FPRICE,/*金融产品交易业务流程.单位全价*/ TPD.CCY,/*金融产品交易业务流程.交易币种*/ TO_CHAR(TPD.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE,/*金融产品交易业务流程.交易日*/ TPD.REMARK,/*金融产品交易业务流程.备注*/ null WORKFLOW_ID,/*金融产品交易业务流程.工作流代码*/ null status,/*金融产品交易业务流程.数据状态*/ TPD.TRADE_AMT TRADE_AMT /*交易金额*/ from TRD_FIN_PRODUCT_DEAL_TOTAL deal left join TRD_PRODUCT_DEAL TPD on deal.TOTLE_TRADE_ID = TPD.TOTLE_TRADE_ID and deal.PS=TPD.PS left join TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID=TPDA.TRADE_ID left join FIN_PRODUCT FP on FP.FINPROD_ID = TPD.FINPROD_ID LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = deal.CHL_ID left join FIN_PRODUCT_TYPE FPT on FP.FINPROD_ID=FPT.FINPROD_ID LEFT JOIN PTL_TRADE PT ON TPD.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID where PP.INVEST_YESORNO = 'Y' AND TPD.IS_CANCEL != #{YES} and TPD.TRADE_STATUS = #{TRADE_STATUS01} AND TPD.PS IN (#{T01}, #{T02}, #{T40}) AND (DEAL.IS_OVERDUE_DEAL IS NULL OR DEAL.IS_OVERDUE_DEAL != 'Y')
UNION ALL
select deal.P_TOTLE_TRADE_ID bizCode, /*金融产品交易业务流程.交易编号*/ '03' statusValid, TPDA.ENTRUST_ID,/*金融产品交易附属业务流程.委托代码*/ fp1.FINPROD_NAME chlFinprodId, PP.PORTFOLIO_ID,/*金融产品交易附属业务流程.投资组合代码*/ PP.PORTFOLIO_NAME,/*组合.组合名称*/ TPD.FINPROD_TYPE2,/*金融产品交易业务流程.金融产品类型*/ TPD.FINPROD_ID,/*金融产品交易业务流程.金融产品代码*/ TPD.CHL_ID chlId,/*金融产品交易业务流程.通道代码*/ FPT.TYPE_6 projectType,/*金融产品分类.行内一级分类*/ FPT.TYPE_9 type9,/*金融产品分类.行内二级分类*/ FPT.TYPE_10 type10,/*金融产品分类.行内三级分类*/ FPT.TYPE_11 type11,/*金融产品分类.行内四级分类*/ FP.FINPROD_MARKET_ID,/*标的类金融产品.市场代码*/ nvl(FP.FINPROD_ABBR, FP.FINPROD_NAME) finprodName,/*标的类金融产品.金融产品简称*/ TPD.PS,/*金融产品交易业务流程.交易方向*/ TPD.PRIN_AMT,/*金融产品交易业务流程.交易本金*/ TPD.UNIT_CPRICE,/*金融产品交易业务流程.单位净价*/ TPD.UNIT_FPRICE,/*金融产品交易业务流程.单位全价*/ TPD.CCY,/*金融产品交易业务流程.交易币种*/ TO_CHAR(TPD.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE,/*金融产品交易业务流程.交易日*/ TPD.REMARK,/*金融产品交易业务流程.备注*/ null WORKFLOW_ID,/*金融产品交易业务流程.工作流代码*/ null status,/*金融产品交易业务流程.数据状态*/ TPD.TRADE_AMT TRADE_AMT /*交易金额*/ from TRD_FIN_PRODUCT_DEAL_TOTAL deal left join TRD_PRODUCT_DEAL TPD on deal.TOTLE_TRADE_ID = TPD.TOTLE_TRADE_ID and deal.PS=TPD.PS left join TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID=TPDA.TRADE_ID left join FIN_PRODUCT FP on FP.FINPROD_ID = TPD.FINPROD_ID LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = deal.CHL_ID left join FIN_PRODUCT_TYPE FPT on FP.FINPROD_ID=FPT.FINPROD_ID LEFT JOIN PTL_TRADE PT ON TPD.P_TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID where PP.INVEST_YESORNO = 'Y' AND TPD.TRADE_STATUS = #{TRADE_STATUS03} AND TPD.PS IN (#{T01}, #{T02}, #{T40}) AND (DEAL.IS_OVERDUE_DEAL IS NULL OR DEAL.IS_OVERDUE_DEAL != 'Y')
UNION ALL SELECT TRD_PRODUCT_DEAL.TRADE_ID AS bizCode, CASE WHEN (TRD_PRODUCT_DEAL.IS_CANCEL != 'Y' and TRD_PRODUCT_DEAL.TRADE_STATUS= '01') THEN '02' ELSE '03' END AS statusValid, TRD_PRODUCT_DEAL_ADD.ENTRUST_ID entrustId, CHLFIN_PRODUCT.FINPROD_NAME AS chlFinprodId, TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID AS portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME AS portfolioName, TRD_PRODUCT_DEAL.FINPROD_TYPE2 as finprodType2, TRD_PRODUCT_DEAL.FINPROD_ID AS finprodId, TRD_PRODUCT_DEAL.CHL_ID AS chlId, FIN_PRODUCT_TYPE.TYPE_6 as projectType, FIN_PRODUCT_TYPE.TYPE_9 as type9, FIN_PRODUCT_TYPE.TYPE_10 as type10, FIN_PRODUCT_TYPE.TYPE_11 as type11, FIN_PRODUCT.FINPROD_MARKET_ID AS finprodMarketId, nvl(FIN_PRODUCT.FINPROD_ABBR, FIN_PRODUCT.FINPROD_NAME) finprodName, TRD_PRODUCT_DEAL.PS AS ps, TRD_PRODUCT_DEAL.PRIN_AMT AS prinAmt, TRD_PRODUCT_DEAL.UNIT_CPRICE, TRD_PRODUCT_DEAL.UNIT_FPRICE, TRD_PRODUCT_DEAL.CCY AS ccy, TO_CHAR(TRD_PRODUCT_DEAL.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE, TRD_PRODUCT_DEAL.REMARK, null WORKFLOW_ID, null status, TRD_PRODUCT_DEAL.TRADE_AMT TRADE_AMT FROM TRD_PRODUCT_DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID LEFT JOIN FIN_PRODUCT CHLFIN_PRODUCT ON CHLFIN_PRODUCT.IS_CHL = 'Y' AND CHLFIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.CHL_ID WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = '01' AND TRD_PRODUCT_DEAL.IS_OUT_TRADE = 'N' AND TRD_PRODUCT_DEAL.TRADE_STATUS != '03' AND FIN_PRODUCT_TYPE.TYPE_8 IN ( 'F06' )
